export const CONSENT_VERSION = "1";

export const MAX_SAMPLES = 3000;

export const MIN_SAMPLE_GAP_MS = 1000;

export const MAX_ACCURACY_M = 50;

export const DRAFT_TTL_MS = 24 * 60 * 60 * 1000;

export type LocationSample = {
  latitude: number;
  longitude: number;
  accuracyM: number;
  timestampMs: number;
};

export type RecordingGap = {
  startMs: number;
  endMs: number;
  reason: "hidden" | "manual";
};

export type MovementStatus = "recording" | "paused" | "ended";

export type MovementDraft = {
  sessionId: string;
  consentVersion: typeof CONSENT_VERSION;
  status: MovementStatus;
  samples: LocationSample[];
  interruptions: RecordingGap[];
  activeMs: number;
  updatedAtMs: number;
};

export type SampleDecision = "accepted" | "invalid" | "inaccurate" | "too_soon" | "full";

export function createMovementDraft(sessionId: string, nowMs: number): MovementDraft {
  return {
    sessionId,
    consentVersion: CONSENT_VERSION,
    status: "recording",
    samples: [],
    interruptions: [],
    activeMs: 0,
    updatedAtMs: nowMs,
  };
}

export function isDraftExpired(updatedAtMs: number, nowMs: number): boolean {
  return nowMs - updatedAtMs > DRAFT_TTL_MS;
}

export function signalFor(accuracyM: number): "clear" | "weak" | "lost" {
  if (!Number.isFinite(accuracyM) || accuracyM > MAX_ACCURACY_M) return "lost";
  if (accuracyM <= 20) return "clear";
  return "weak";
}

export function acceptSample(
  draft: MovementDraft,
  sample: LocationSample,
  nowMs: number,
): { draft: MovementDraft; decision: SampleDecision } {
  if (!isValidSample(sample)) return { draft, decision: "invalid" };
  if (sample.accuracyM > MAX_ACCURACY_M) return { draft, decision: "inaccurate" };
  if (draft.samples.length >= MAX_SAMPLES) return { draft, decision: "full" };
  const last = draft.samples[draft.samples.length - 1];
  if (last && sample.timestampMs < last.timestampMs) return { draft, decision: "invalid" };
  if (last && sample.timestampMs - last.timestampMs < MIN_SAMPLE_GAP_MS) {
    return { draft, decision: "too_soon" };
  }
  return {
    decision: "accepted",
    draft: {
      ...draft,
      samples: [...draft.samples, sample],
      updatedAtMs: nowMs,
    },
  };
}

export function parseMovementDraft(value: unknown): MovementDraft | null {
  if (!value || typeof value !== "object") return null;
  const draft = value as MovementDraft;
  if (draft.consentVersion !== CONSENT_VERSION) return null;
  if (draft.status !== "recording" && draft.status !== "paused" && draft.status !== "ended") {
    return null;
  }
  if (!isId(draft.sessionId) || !isDuration(draft.activeMs) || !isTime(draft.updatedAtMs)) {
    return null;
  }
  if (!Array.isArray(draft.samples) || draft.samples.length > MAX_SAMPLES) return null;
  if (!draft.samples.every(isValidSample)) return null;
  if (!Array.isArray(draft.interruptions) || draft.interruptions.length > 64) return null;
  if (!draft.interruptions.every(isGap)) return null;
  const ordered = draft.samples.every((sample, index) => {
    const previous = draft.samples[index - 1];
    return !previous || sample.timestampMs - previous.timestampMs >= MIN_SAMPLE_GAP_MS;
  });
  if (!ordered) return null;
  return {
    sessionId: draft.sessionId,
    consentVersion: CONSENT_VERSION,
    status: draft.status,
    samples: draft.samples.map((sample) => ({ ...sample })),
    interruptions: draft.interruptions.map((gap) => ({ ...gap })),
    activeMs: draft.activeMs,
    updatedAtMs: draft.updatedAtMs,
  };
}

function isValidSample(value: unknown): value is LocationSample {
  if (!value || typeof value !== "object") return false;
  const sample = value as LocationSample;
  return (
    Number.isFinite(sample.latitude) &&
    sample.latitude >= -90 &&
    sample.latitude <= 90 &&
    Number.isFinite(sample.longitude) &&
    sample.longitude >= -180 &&
    sample.longitude <= 180 &&
    Number.isFinite(sample.accuracyM) &&
    sample.accuracyM >= 0 &&
    isTime(sample.timestampMs)
  );
}

function isGap(value: unknown): value is RecordingGap {
  if (!value || typeof value !== "object") return false;
  const gap = value as RecordingGap;
  return (
    isTime(gap.startMs) &&
    isTime(gap.endMs) &&
    gap.endMs >= gap.startMs &&
    (gap.reason === "hidden" || gap.reason === "manual")
  );
}

function isId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && value.length <= 80 && !value.includes("\n");
}

function isDuration(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

function isTime(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value > 0;
}

import { isDraftExpired, parseMovementDraft, type MovementDraft } from "./movementDraft";

export const DRAFT_DB = "footwork";

export const DRAFT_STORE = "drafts";

export const DRAFT_KEY = "current";

export type DraftStore = {
  read: (nowMs: number) => Promise<MovementDraft | null>;
  write: (draft: MovementDraft) => Promise<void>;
  clear: () => Promise<void>;
};

export function createDraftStore(factory: IDBFactory = indexedDB): DraftStore {
  return {
    async read(nowMs) {
      const db = await openDb(factory);
      try {
        const stored = await request<unknown>(
          db.transaction(DRAFT_STORE, "readonly").objectStore(DRAFT_STORE).get(DRAFT_KEY),
        );
        const draft = parseMovementDraft(stored);
        if (!draft) return null;
        if (isDraftExpired(draft.updatedAtMs, nowMs)) {
          await deleteCurrent(db);
          return null;
        }
        return draft;
      } finally {
        db.close();
      }
    },
    async write(draft) {
      const parsed = parseMovementDraft(draft);
      if (!parsed) throw new Error("Draft is not storable");
      const db = await openDb(factory);
      try {
        await request(
          db.transaction(DRAFT_STORE, "readwrite").objectStore(DRAFT_STORE).put(parsed, DRAFT_KEY),
        );
      } finally {
        db.close();
      }
    },
    async clear() {
      const db = await openDb(factory);
      try {
        await deleteCurrent(db);
      } finally {
        db.close();
      }
    },
  };
}

function openDb(factory: IDBFactory): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const open = factory.open(DRAFT_DB, 1);
    open.onupgradeneeded = () => {
      const db = open.result;
      if (!db.objectStoreNames.contains(DRAFT_STORE)) db.createObjectStore(DRAFT_STORE);
    };
    open.onsuccess = () => resolve(open.result);
    open.onerror = () => reject(open.error ?? new Error("Draft store failed to open"));
  });
}

function deleteCurrent(db: IDBDatabase): Promise<void> {
  return request(db.transaction(DRAFT_STORE, "readwrite").objectStore(DRAFT_STORE).delete(DRAFT_KEY));
}

function request<T>(query: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    query.onsuccess = () => resolve(query.result);
    query.onerror = () => reject(query.error ?? new Error("Draft store request failed"));
  });
}

import {
  acceptSample,
  createMovementDraft,
  signalFor,
  type LocationSample,
  type MovementDraft,
} from "./movementDraft";

export type LivePhase =
  | "ready"
  | "checking_location"
  | "recording"
  | "pausing"
  | "paused"
  | "resuming"
  | "ending"
  | "finished"
  | "permission_denied"
  | "unsupported_browser"
  | "offline";

export type LiveModel = {
  phase: LivePhase;
  draft: MovementDraft | null;
  watching: boolean;
  signal: "clear" | "weak" | "lost";
  baseActiveMs: number;
  resumeNote: string | null;
  saveError: string | null;
};

const STARTABLE = new Set<LivePhase>([
  "ready",
  "permission_denied",
  "unsupported_browser",
  "offline",
  "finished",
]);

export function initialLive(): LiveModel {
  return {
    phase: "ready",
    draft: null,
    watching: false,
    signal: "lost",
    baseActiveMs: 0,
    resumeNote: null,
    saveError: null,
  };
}

export function recoverLive(saved: MovementDraft | null): LiveModel {
  if (!saved || saved.status === "ended") return initialLive();
  return {
    phase: saved.status === "paused" ? "paused" : "recording",
    draft: saved,
    watching: saved.status === "recording",
    signal: "lost",
    baseActiveMs: saved.activeMs,
    resumeNote: null,
    saveError: null,
  };
}

export function beginLive(
  state: LiveModel,
  support: "ok" | "unsupported",
  online: boolean,
): LiveModel {
  if (!STARTABLE.has(state.phase)) return state;
  if (support === "unsupported") return { ...initialLive(), phase: "unsupported_browser" };
  if (!online) return { ...initialLive(), phase: "offline" };
  return { ...initialLive(), phase: "checking_location", watching: true };
}

export function notePosition(
  state: LiveModel,
  sample: LocationSample,
  nowMs: number,
  sessionId: string,
  activeMs: number,
): LiveModel {
  if (!state.watching) return state;
  const signal = signalFor(sample.accuracyM);
  if (state.phase === "checking_location") {
    const opened = acceptSample(createMovementDraft(sessionId, nowMs), sample, nowMs);
    if (opened.decision !== "accepted") return { ...state, signal };
    return {
      ...state,
      phase: "recording",
      signal,
      baseActiveMs: 0,
      draft: { ...opened.draft, activeMs },
    };
  }
  if ((state.phase === "recording" || state.phase === "resuming") && state.draft) {
    const recording = { ...state.draft, status: "recording" as const };
    const accepted = acceptSample(recording, sample, nowMs);
    const draft = accepted.decision === "accepted" ? accepted.draft : state.draft;
    return {
      ...state,
      phase: "recording",
      signal,
      resumeNote: null,
      draft: { ...draft, status: "recording", activeMs, updatedAtMs: nowMs },
    };
  }
  return state;
}

export function noteDenied(state: LiveModel): LiveModel {
  if (state.phase === "resuming") {
    return {
      ...state,
      phase: "paused",
      watching: false,
      resumeNote: "This site cannot use your location yet. Your walk is still paused.",
    };
  }
  if (state.phase !== "checking_location") return state;
  return { ...initialLive(), phase: "permission_denied" };
}

export function pauseLive(state: LiveModel, activeMs: number, nowMs: number): LiveModel {
  if (state.phase !== "recording" || !state.draft) return state;
  return {
    ...state,
    phase: "pausing",
    watching: false,
    baseActiveMs: activeMs,
    draft: { ...state.draft, status: "paused", activeMs, updatedAtMs: nowMs },
  };
}

export function markPaused(state: LiveModel): LiveModel {
  if (state.phase !== "pausing") return state;
  return { ...state, phase: "paused", watching: false };
}

export function resumeLive(state: LiveModel, online: boolean): LiveModel {
  if (state.phase !== "paused" || !state.draft) return state;
  if (!online) {
    return {
      ...state,
      watching: false,
      resumeNote: "You appear to be offline. Your walk is still paused.",
    };
  }
  return { ...state, phase: "resuming", watching: true, resumeNote: null };
}

export function endLive(state: LiveModel, activeMs: number, nowMs: number): LiveModel {
  if (!state.draft) return { ...state, watching: false, phase: "finished" };
  if (state.phase !== "recording" && state.phase !== "paused" && state.phase !== "pausing") {
    return state;
  }
  return {
    ...state,
    phase: "ending",
    watching: false,
    baseActiveMs: activeMs,
    draft: { ...state.draft, status: "ended", activeMs, updatedAtMs: nowMs },
  };
}

export function markFinished(state: LiveModel): LiveModel {
  if (state.phase !== "ending") return state;
  return { ...state, phase: "finished", watching: false };
}

export function cancelLive(state: LiveModel): LiveModel {
  if (state.phase === "checking_location" || state.phase === "resuming") {
    return state.draft && state.phase === "resuming"
      ? { ...state, phase: "paused", watching: false }
      : initialLive();
  }
  return initialLive();
}

export function failSave(state: LiveModel): LiveModel {
  return { ...state, saveError: "This walk could not be saved on this phone." };
}

import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "../ui/Button";
import { Sheet } from "../ui/Sheet";
import { LandingView } from "./LandingView";
import { RecordingView, type RecordingPhase } from "./RecordingView";
import { createDraftStore } from "./draftStore";
import {
  beginLive,
  cancelLive,
  endLive,
  failSave,
  initialLive,
  markFinished,
  markPaused,
  noteDenied,
  notePosition,
  pauseLive,
  recoverLive,
  resumeLive,
  type LiveModel,
  type LivePhase,
} from "./liveCapture";
import type { LocationSample } from "./movementDraft";
import type { RecordingPort } from "./practicePort";
import { useRunningOffset } from "./useMonotonicClock";

type Navigate = (event: { preventDefault: () => void; currentTarget: { href: string } }) => void;

const WATCH_OPTIONS: PositionOptions = {
  enableHighAccuracy: true,
  maximumAge: 0,
  timeout: 20000,
};

export function LiveWalk({ onNavigate }: { onNavigate: Navigate }) {
  const store = useMemo(() => createDraftStore(), []);
  const [model, setModel] = useState<LiveModel>(initialLive);
  const [settled, setSettled] = useState(false);
  const [sheetOpen, setSheetOpen] = useState(false);
  const modelRef = useRef(model);
  const sessionRef = useRef("");
  const readActiveRef = useRef(() => 0);
  modelRef.current = model;
  const recording = model.phase === "recording";
  const activeClock = useRunningOffset(recording);
  readActiveRef.current = () => modelRef.current.baseActiveMs + (recording ? activeClock.read() : 0);

  useEffect(() => {
    let cancel = false;
    void store.read(Date.now()).then((saved) => {
      if (cancel) return;
      const recovered = recoverLive(saved);
      if (recovered.draft) sessionRef.current = recovered.draft.sessionId;
      setModel(recovered);
      setSettled(true);
    });
    return () => {
      cancel = true;
    };
  }, [store]);

  useEffect(() => {
    if (!model.watching || !navigator.geolocation) return;
    const watchId = navigator.geolocation.watchPosition(onPosition, onError, WATCH_OPTIONS);
    return () => navigator.geolocation.clearWatch(watchId);

    function onPosition(position: GeolocationPosition) {
      const sample: LocationSample = {
        latitude: position.coords.latitude,
        longitude: position.coords.longitude,
        accuracyM: position.coords.accuracy,
        timestampMs: position.timestamp,
      };
      if (!sessionRef.current) sessionRef.current = crypto.randomUUID();
      const next = notePosition(
        modelRef.current,
        sample,
        Date.now(),
        sessionRef.current,
        readActiveRef.current(),
      );
      modelRef.current = next;
      setModel(next);
    }

    function onError(error: GeolocationPositionError) {
      if (error.code !== error.PERMISSION_DENIED) return;
      const next = noteDenied(modelRef.current);
      modelRef.current = next;
      setModel(next);
    }
  }, [model.watching]);

  useEffect(() => {
    if (!model.draft) return;
    let cancel = false;
    void store.write(model.draft).catch(() => {
      if (cancel) return;
      setModel((current) => {
        const next = failSave(current);
        modelRef.current = next;
        return next;
      });
    });
    return () => {
      cancel = true;
    };
  }, [model.draft, store]);

  useEffect(() => {
    if (model.phase !== "pausing") return;
    const timer = window.setTimeout(() => {
      setModel((current) => {
        const next = markPaused(current);
        modelRef.current = next;
        return next;
      });
    }, 1000);
    return () => window.clearTimeout(timer);
  }, [model.phase]);

  useEffect(() => {
    if (model.phase !== "ending") return;
    const timer = window.setTimeout(() => {
      setModel((current) => {
        const next = markFinished(current);
        modelRef.current = next;
        return next;
      });
    }, 700);
    return () => window.clearTimeout(timer);
  }, [model.phase]);

  const port = useMemo<RecordingPort>(
    () => ({
      mode: "live",
      scenario: "granted",
      checkSupport: () => (navigator.geolocation ? "ok" : "unsupported"),
      explainThenResolve: () => (navigator.onLine ? "granted" : "offline"),
      wakeLockLabel: () => "Screen awake is not held. The phone may still sleep.",
      signalLabel: () => `Signal: ${model.signal}`,
      recoverDraft: () => null,
      saveDraft: () => undefined,
      clearDraft: () => undefined,
      reacquireFix: () => "ready",
    }),
    [model.signal],
  );

  const clocks = {
    activeMs: model.baseActiveMs + (recording ? activeClock.displayMs : 0),
    breakMs: 0,
    currentBreakMs: 0,
    elapsedMs: model.baseActiveMs + (recording ? activeClock.displayMs : 0),
  };

  const apply = (next: LiveModel) => {
    modelRef.current = next;
    setModel(next);
  };

  const reset = () => {
    sessionRef.current = "";
    setSheetOpen(false);
    apply(initialLive());
    void store.clear();
  };

  const begin = () => {
    setSheetOpen(false);
    sessionRef.current = crypto.randomUUID();
    apply(
      beginLive(
        modelRef.current,
        navigator.geolocation ? "ok" : "unsupported",
        navigator.onLine,
      ),
    );
  };

  return (
    <>
      {!settled || model.phase === "ready" ? (
        <LandingView
          onStart={() => {
            if (settled) setSheetOpen(true);
          }}
          onNavigate={onNavigate}
        />
      ) : (
        <RecordingView
          phase={model.phase as RecordingPhase}
          clocks={clocks}
          draft={null}
          liveSegmentMs={activeClock.displayMs}
          sampleCount={model.draft?.samples.length ?? 0}
          port={port}
          resumeNote={model.resumeNote}
          saveError={model.saveError}
          onCancel={() => {
            if (model.phase === "resuming") {
              apply(cancelLive(modelRef.current));
              return;
            }
            reset();
          }}
          onPause={() => apply(pauseLive(modelRef.current, readActiveRef.current(), Date.now()))}
          onResume={() => apply(resumeLive(modelRef.current, navigator.onLine))}
          onCancelResume={() => apply(cancelLive(modelRef.current))}
          onEnd={() => apply(endLive(modelRef.current, readActiveRef.current(), Date.now()))}
          onRetry={reset}
          onNavigate={onNavigate}
        />
      )}
      <Sheet
        open={sheetOpen}
        title="Before you walk"
        closeLabel="Not now"
        onClose={() => setSheetOpen(false)}
      >
        <p>
          Footwork will ask this browser for your location and keep the walk on this phone. It does
          not upload a route.
        </p>
        <Button onClick={begin}>Use my location</Button>
      </Sheet>
    </>
  );
}

export function isLivePhase(phase: LivePhase): boolean {
  return phase !== "ready";
}

